from collections import deque

window = deque(maxlen=3)
for x in [10, 20, 30, 40, 50]:
    window.append(x)
    print(sum(window) / len(window))

graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
queue, seen, order = deque(["A"]), {"A": True}, []
while queue:
    v = queue.popleft()
    order.append(v)
    for u in graph[v]:
        if u not in seen:
            seen[u] = True
            queue.append(u)
print(order)
